arguments.command:
cat > /tmp/stackalloc_nint.cs << 'EOF'
// Test stackalloc with Span<nint> and Span<nuint>
Span<nint> signedSpan = stackalloc nint[5];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Span<nuint> unsignedSpan = stackalloc nuint[3];
for (int i = 0; i < unsignedSpan.Length; i++)
    unsignedSpan[i] = (nuint)(i + 100);

Console.WriteLine($"Span<nint> length: {signedSpan.Length}, values: {signedSpan[0]}, {signedSpan[1]}, {signedSpan[2]}, {signedSpan[3]}, {signedSpan[4]}");
Console.WriteLine($"Span<nuint> length: {unsignedSpan.Length}, values: {unsignedSpan[0]}, {unsignedSpan[1]}, {unsignedSpan[2]}");
Console.WriteLine($"nint size: {sizeof(nint)} bytes");
EOF
